fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo, switch to Data Explorer, and open the Queries section. Then walk these interactions IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) query-info-sql — select any Approved query (green status dot) from the folder tree so it opens in the right-hand viewer, then click the 'Info' button in the viewer header to open the Query Information slide-in and expand the 'SQL Query' accordion section so the read-only SQL renders in a code editor; (2) query-export-dialog — select a no-parameter Approved query so it auto-runs and the results grid populates, then click the 'Export' button (file-export icon) in the results toolbar to open the export dialog with format/options controls (you do NOT need to complete the download; if a query returns zero rows pick another Approved query that returns rows); (3) query-param-roundtrip — using the 'Search queries...' box find a query that HAS parameters (its tree row shows a sliders/parameter icon), select it, click 'Parameters' in the viewer header to open the Query Parameters slide-in, enter a value into a typed parameter input and click 'Run Query', then confirm the results grid re-runs and shows results or a valid 'No results' empty state. Keep going until all three interactions are done. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "query-info-sql",
      "instruction": "Query Info panel + rendered SQL view",
      "visualCriteria": [
        "The Query Information slide-in panel opens with accordion sections (Overview, Fields, Parameters, SQL Query), and expanding the 'SQL Query' section shows the query's SQL text in a read-only code editor (or a clear 'SQL not available' empty state)"
      ]
    },
    {
      "name": "query-export-dialog",
      "instruction": "Results grid Export dialog",
      "visualCriteria": [
        "After a query runs and its results grid populates, clicking Export opens an export dialog with export format/options controls"
      ]
    },
    {
      "name": "query-param-roundtrip",
      "instruction": "Parameterized query execution round-trip",
      "visualCriteria": [
        "The Query Parameters slide-in opens with typed input field(s) and a 'Run Query' button, and after entering a value and clicking Run Query the results grid re-runs and shows results or a valid 'No results' empty state"
      ]
    }
  ]
}
